// === Tab: mySketch ===
let simplex 
let gs
let waveBoxes=[]

function setup() {
	let w=max(windowWidth, windowHeight)
	createCanvas(1112, 834);
	colorMode(HSB, 255);
	gs=w/8
	background(0);
	simplex= new OpenSimplexNoise(Date.now())

	let n=0.1
	for(let x=gs/2; x<width+gs; x+=gs){
		for(let y=gs/2; y<height+gs; y+=gs){
	    waveBoxes.push(new waveBox(x, y, gs, gs, 30, n))
			n+=0.1
		}
	}
}

function draw() {
	background(0)
	for(let w of waveBoxes){
		w.show()
	}

}


class waveBox{
	constructor(x, y, w, h, nodes, n){
		this.pos=createVector(x, y)
		this.w=w
		this.h=h
		this.nodes=nodes
		this.n=n
	}

	show(){
		for(let i=0; i<3; i+=3/this.nodes){
		let x= this.pos.x+map(simplex.noise3D(this.pos.x/10+this.n, frameCount/100-i, frameCount/200),-0.8, 0.8, -this.w/2, this.w/2)
		let y= this.pos.y+map(simplex.noise3D(this.pos.y/10, frameCount/100-i, frameCount/200),-0.8, 0.8, -this.h/2, this.h/2)
		let strokeW=map(i, 3, 0, 1, gs/2)
		let strokeB=map(i, 3, 0, 255, 0)
		strokeWeight(strokeW)
		stroke(255-strokeB, 255, 255)
		point(x, y)
		}
		strokeWeight(1)
	}
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
    lapse = millis();
  } 
}

